const T=n=>n*(n+1)/2, S=n=>1+6*n*(n-1), D=n=>n*(3*n-1)*(3*n-2)/2, Tet=n=>n*(n+1)*(n+2)/6;
const checks={}; function check(k,v){checks[k]=!!v}
const range=Array.from({length:100},(_,i)=>i+1);
check("historical_center",range.every(n=>S(n)===1+6*(n-1)+6*(n-1)**2));
check("historical_unique",JSON.stringify(range.filter(n=>1+6*(n-1)===T(n)))==="[1,10]");
check("historical_dod",range.every(n=>D(n)===Tet(3*n-2)));
check("historical_shell",range.slice(1).every(n=>D(n)-D(n-1)===1+3*T(3*n-3)));
check("historical_midpoint",range.every(n=>S(n)+S(n+1)===2*(6*n*n+1)));
check("historical_275",Tet(16)-S(10)===275);
check("ABC_polynomial",JSON.stringify(range.slice(0,6).map(x=>(x+1)*(x+3)*(x+6)))==="[56,120,216,350,528,756]");
check("ABC_powers",range.every(n=>(1n+3n**BigInt(n)+6n**BigInt(n))%9n===1n));
check("ABC_shell",range.every(n=>((1+3*n*(n+1))%9===1)===(n%3!==1)));
const alternatives=[]; for(let i=1;i<=12;i++)for(let j=i+1;j<=12;j++)for(let k=j+1;k<=12;k++){let a=T(i),b=T(j),c=T(k);if(a%9===1&&b%3===0&&c%3===0&&(a+b+c)%9===1)alternatives.push([i,j,k,a,b,c]);}
check("ABC_nonunique",alternatives.length>1);
const result={checks,alternatives,alternative_count:alternatives.length,passed:Object.values(checks).filter(Boolean).length,failed:Object.values(checks).filter(x=>!x).length};
console.log(JSON.stringify(result,null,2));
